int main(){using namespace cellerator::compiler::ir::planning::v1;for(unsigned i=0;i<8;++i){search_space_edit_v1 x{{1,i+1},{2,1},{3,1},{4,1},static_cast<search_edit_kind_v1>(i),i==6?edit_authority_v1::user_force:i==7?edit_authority_v1::unsafe_user_assertion:edit_authority_v1::compiler_pass,static_cast<std::uint8_t>(i==7),0,10+i,1};assert(validate_search_space_edit_v1(x,10)==search_edit_status_v1::ok);}search_space_edit_v1 hint{{1,1},{2,1},{3,1},{},search_edit_kind_v1::change_cost,edit_authority_v1::source_hint,0,0,10,1};auto forced=hint;forced.edit={1,2};forced.authority=edit_authority_v1::user_force;assert(edit_overrides_v1(forced,hint));forced.kind=search_edit_kind_v1::unsafe_assertion;assert(validate_search_space_edit_v1(forced,0)==search_edit_status_v1::unsafe_not_acknowledged);}
